implementation_evidence.quote:
if len(options) < 2:
    raise DocumentValidationError(
        f"Question {number} ('{item['text'][:60]}') needs at least 2 answer options"
    )

if existing is not None:
    raise HTTPException(
        status_code=409,
        detail="This question has already been answered; answers cannot be changed (R14)",
    )

const result = await quizApi.startQuiz({
  documentId: state.documentId,
  mode,
  questionOrder,
  questionCount,
});

if (mode === "learning") {
  answer.isCorrect = result.isMarkedCorrect;
  answer.correctOptionId = result.correctOptionId;
  answer.correctOptionText = result.correctOptionText;
  answer.explanation = result.explanation;
}

quizApi
  .getResults(attemptId)
  .then((data) => {
    if (!cancelled) {
      setResults(data);
      setError(null);
      setLocked(false);
    }
  })
  .catch((err: any) => {
    if (cancelled) return;
    if (err?.status === 403) {
      setLocked(true);

const handleRestart = useCallback(() => {
  resetSession(); // clears attempt, answers and progress (R25)
  navigate("/configure");
}, [navigate, resetSession]);
